export function getAllBrandSocialPages(): BrandSocialPageData[] {
  return BRAND_SOCIAL_PAGES;
}

export function getBrandSocialPageByPath(path: string): BrandSocialPageData | undefined {
  const norm = path.replace(/\/+$/, '') || '/';
  return BRAND_SOCIAL_PAGES.find(p => p.path.replace(/\/+$/, '') === norm);
}

export function getBrandSocialPageById(id: string): BrandSocialPageData | undefined {
  return BRAND_SOCIAL_PAGES.find(p => p.id === id);
}

export function getBrandSocialPagesByCol(col: string): BrandSocialPageData[] {
  return BRAND_SOCIAL_PAGES.filter(p => p.col === col);
}

export function getBrandSocialSlugs(colPrefix: string): string[] {
  return BRAND_SOCIAL_PAGES
    .filter(p => !p.hub && p.path.startsWith(colPrefix + '/'))
    .map(p => p.path.replace(colPrefix + '/', ''));
}
